 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Full uniform separator rows/columns divide the grid into repeated panels.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    def spans(n, seps):
        out, start = [], 0
        for i in seps:
            if start < i:
                out.append((start, i))
            start = i + 1
        if start < n:
            out.append((start, n))
        return out
    rs, cs = spans(h, sep_rows), spans(w, sep_cols)
    # The panel with most non-background marks is the exemplar; other panels
    # are filled by repeating it, preserving the separator bands.
    panel_cells = [grid[r][c] for r0,r1 in rs for c0,c1 in cs
                   for r in range(r0,r1) for c in range(c0,c1)]
    bg = Counter(panel_cells).most_common(1)[0][0]
    best = None
    for r0,r1 in rs:
        for c0,c1 in cs:
            score = sum(grid[r][c] != bg for r in range(r0,r1) for c in range(c0,c1))
            if best is None or score > best[0]:
                best = (score, r0, r1, c0, c1)
    _, r0,r1,c0,c1 = best
    ph, pw = r1-r0, c1-c0
    out = [row[:] for row in grid]
    for ir,(a,b) in enumerate(rs):
        for ic,(x,y) in enumerate(cs):
            for r in range(a,b):
                for c in range(x,y):
                    out[r][c] = grid[r0 + (r-a)%ph][c0 + (c-x)%pw]
    return out
